61:## Import
62-
63-`POST /groups/:id/import` records a list of expenses and payments for a group in one go: all of them, or none of them.
64-
65-The body is `{"entries": [...], "dry_run": <boolean>, "skip_recorded": <boolean>}`. `dry_run` and `skip_recorded` may be left out, and are then false. An entry is either an expense `{"type": "expense", "description", "payer", "amount", "split"}`, where `split` may be left out, or a payment `{"type": "payment", "from", "to", "amount"}`. Each field follows the same rule as on `POST /groups/:id/expenses` or `POST /groups/:id/payments`. A field counts as left out only when its key is absent: a present key is checked whatever its value, `null` included.
66-
67-After the 413 and non-object checks every route has, these checks run in order; the first that fails decides the reply, and a failed check saves nothing:
68-
69-1. Unknown group: 404 `{"error": "not found"}`.
70-2. 400 `{"error": "<message>"}`, the first that applies: `unknown field <name>` (any body field other than `entries`, `dry_run` and `skip_recorded`; the first one in `Object.keys` order), `entries must be an array of 1 to 50 items`, `dry_run must be true or false`, `skip_recorded must be true or false`.
71-3. 422 `{"error": "import rejected", "problems": [{"index", "rule"}, ...]}` when any entry breaks a rule: one item per such entry, sorted by `index` (its position in `entries`, from 0), with the first rule it breaks, in this order:
72-   - `not-an-object`: the entry is not a JSON object (null and arrays are not objects).
73-   - `bad-type`: `type` is not `"expense"` or `"payment"`.
74-   - `unknown-field`: a field its type does not take. An expense takes `type`, `description`, `payer`, `amount` and `split`; a payment takes `type`, `from`, `to` and `amount`.
75-   - Expense: `bad-description`, `bad-payer`, `bad-amount`, `bad-split`; then `duplicate` when an earlier entry that broke none of the rules above is an expense with the same payer, amount and description; then `already-recorded` when the group already has an expense with the same payer, amount and description. Descriptions are compared after `trim()` and `toLowerCase()`, amounts in cents; `split` is not compared. An earlier entry counts for `duplicate` even when it is itself `duplicate` or `already-recorded`, skipped or not.
76-   - Payment: `bad-from` (`from` is not a member), `bad-to` (`to` is not a member, or is `from`), `bad-amount`. Payments are never `duplicate` or `already-recorded`.
77-
78-   With `"skip_recorded": true`, an entry whose first broken rule is `already-recorded` is skipped instead of being a problem.
79-4. Success: 201 `{"expenses": [...], "payments": [...], "skipped": [...], "balances": {...}}`. Each entry that is not skipped becomes an expense or a payment exactly as the POST routes would make it, with consecutive ids of its kind in entry order, starting at the next id; the whole import is saved in one write. `expenses` and `payments` list the new ones in entry order, `skipped` the indexes of skipped entries in ascending order, and `balances` the group's balances after the import, as `GET /groups/:id/balances` gives them. When every entry is skipped, nothing is written.
80-
81-With `"dry_run": true`, the checks and error replies are the same, and a passing import gets the same body with status 200, but nothing is saved: the ids shown are the ones a real import would get now.
82-
83-## Layout
84-
85-- `server.mjs`: start-up, and the request loop: find the route, read the body, run the handler, save.
86-- `lib/http.mjs`: body reading, JSON replies, errors.
87-- `lib/routes.mjs`: route table.
88-- `lib/groups.mjs`, `lib/expenses.mjs`, `lib/import.mjs`: handlers. Handlers return a new store instead of changing the old one.
89-- `lib/validate.mjs`: input parsers; they throw `ValidationError` (400).
90-- `lib/ledger.mjs`: money maths on cents: shares, balances, and how expenses and payments are shown.
91-- `lib/store.mjs`: loading and atomic saving of the data file.
92-- `test/`: `node:test` suites; `helpers.mjs` starts the app on a free port with a temp data file.
// POST /groups/:id/import: records a list of expenses and payments for a group in one write, all or none.
// Same handler contract as lib/groups.mjs: it returns a new store instead of changing the one it gets.
import { NOT_FOUND, findGroup } from './groups.mjs'
import { balances, expenseView, paymentView } from './ledger.mjs'
import { parseAmount, parseDescription, parseMember, parseSplit, ValidationError } from './validate.mjs'

const BODY_FIELDS = ['entries', 'dry_run', 'skip_recorded']
const MAX_ENTRIES = 50
const ENTRY_FIELDS = {
  expense: ['type', 'description', 'payer', 'amount', 'split'],
  payment: ['type', 'from', 'to', 'amount'],
}

// A rule broken by one entry; caught per entry and listed in the 422 reply.
class EntryProblem extends Error {
  constructor(rule) {
    super(rule)
    this.rule = rule
  }
}

// Runs parse, turning its ValidationError into the entry rule `rule`.
function check(rule, parse) {
  try {
    return parse()
  } catch (err) {
    if (err instanceof ValidationError) throw new EntryProblem(rule)
    throw err
  }
}

// Checks the body fields in the order the README lists them; throws ValidationError (400) on the first bad one.
function parseImportBody(body) {
  const unknown = Object.keys(body).find(key => !BODY_FIELDS.includes(key))
  if (unknown !== undefined) throw new ValidationError(`unknown field ${unknown}`)
  const { entries } = body
  if (!Array.isArray(entries) || entries.length < 1 || entries.length > MAX_ENTRIES) {
    throw new ValidationError(`entries must be an array of 1 to ${MAX_ENTRIES} items`)
  }
  const flag = name => {
    if (!Object.hasOwn(body, name)) return false
    if (typeof body[name] !== 'boolean') throw new ValidationError(`${name} must be true or false`)
    return body[name]
  }
  return { entries, dryRun: flag('dry_run'), skipRecorded: flag('skip_recorded') }
}

// One entry as { type, fields }, the fields as the POST routes would store them; throws EntryProblem.
function parseEntry(entry, group) {
  if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) throw new EntryProblem('not-an-object')
  const { type } = entry
  if (type !== 'expense' && type !== 'payment') throw new EntryProblem('bad-type')
  if (Object.keys(entry).some(key => !ENTRY_FIELDS[type].includes(key))) throw new EntryProblem('unknown-field')
  const { members } = group
  if (type === 'expense') {
    // The same parsers, in the same order, as POST /groups/:id/expenses; a missing split means every member.
    const fields = {
      description: check('bad-description', () => parseDescription(entry.description)),
      payer: check('bad-payer', () => parseMember(entry.payer, members, 'bad payer')),
      amount: check('bad-amount', () => parseAmount(entry.amount)),
      split: check('bad-split', () => parseSplit(entry.split, members)),
    }
    return { type, fields }
  }
  const from = check('bad-from', () => parseMember(entry.from, members, 'bad from'))
  const to = check('bad-to', () => parseMember(entry.to, members, 'bad to'))
  if (to === from) throw new EntryProblem('bad-to')
  return { type, fields: { from, to, amount: check('bad-amount', () => parseAmount(entry.amount)) } }
}

// Expenses match when payer, amount in cents and description (trimmed, lower case) are the same.
const expenseKey = ({ payer, amount, description }) => JSON.stringify([payer, amount, description.trim().toLowerCase()])

export function importEntries({ state, params, body }) {
  const group = findGroup(state, params[0])
  if (!group) return NOT_FOUND
  const { entries, dryRun, skipRecorded } = parseImportBody(body)

  const recorded = new Set(state.expenses.filter(e => e.group === group.id).map(expenseKey))
  const seen = new Set()
  const problems = []
  const accepted = []
  const skipped = []
  entries.forEach((entry, index) => {
    let parsed
    try {
      parsed = parseEntry(entry, group)
    } catch (err) {
      if (!(err instanceof EntryProblem)) throw err
      problems.push({ index, rule: err.rule })
      return
    }
    if (parsed.type === 'expense') {
      const key = expenseKey(parsed.fields)
      const isDuplicate = seen.has(key)
      seen.add(key)
      if (isDuplicate) {
        problems.push({ index, rule: 'duplicate' })
        return
      }
      if (recorded.has(key)) {
        if (skipRecorded) skipped.push(index)
        else problems.push({ index, rule: 'already-recorded' })
        return
      }
    }
    accepted.push(parsed)
  })
  if (problems.length > 0) return { status: 422, body: { error: 'import rejected', problems } }

  let { nextExpenseId, nextPaymentId } = state
  const expenses = []
  const payments = []
  for (const { type, fields } of accepted) {
    if (type === 'expense') expenses.push({ id: nextExpenseId++, group: group.id, ...fields })
    else payments.push({ id: nextPaymentId++, group: group.id, ...fields })
  }
  const next = {
    ...state,
    expenses: [...state.expenses, ...expenses],
    payments: [...state.payments, ...payments],
    nextExpenseId,
    nextPaymentId,
  }
  const reply = {
    status: dryRun ? 200 : 201,
    body: {
      expenses: expenses.map(expenseView),
      payments: payments.map(paymentView),
      skipped,
      balances: balances(next, group),
    },
  }
  // Nothing to write on a dry run, or when every entry was skipped.
  return dryRun || accepted.length === 0 ? reply : { ...reply, state: next }
}
import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createApp } from '../server.mjs'

// A data file in a fresh temp folder; cleanup() deletes the folder.
export function tempDataFile() {
  const dir = mkdtempSync(join(tmpdir(), 'split-test-'))
  return { file: join(dir, 'groups.json'), cleanup: () => rmSync(dir, { recursive: true, force: true }) }
}

// Starts the app on a free port. call(method, path, body) sends one request; stop() closes the server.
export async function startApp(dataFile) {
  const server = createApp(dataFile)
  await new Promise((resolve, reject) => {
    server.once('error', reject)
    server.listen(0, '127.0.0.1', resolve)
  })
  const base = `http://127.0.0.1:${server.address().port}`
  return {
    call: (method, path, body) => request(base + path, method, body),
    stop: () => new Promise(resolve => server.close(resolve)),
  }
}

// Runs fn with a running app on its own data file, then stops it and deletes the file.
export async function withApp(fn) {
  const data = tempDataFile()
  const app = await startApp(data.file)
  try {
    await fn(app.call)
  } finally {
    await app.stop()
    data.cleanup()
  }
}

async function request(url, method, body) {
  const init = { method }
  if (body !== undefined) {
    init.headers = { 'content-type': 'application/json' }
    init.body = typeof body === 'string' ? body : JSON.stringify(body)
  }
  const res = await fetch(url, init)
  const text = await res.text()
  const isJson = (res.headers.get('content-type') ?? '').startsWith('application/json')
  return { status: res.status, headers: res.headers, text, body: isJson ? JSON.parse(text) : undefined }
}
